import{_ as n,C as r,o as d,c as i,j as e,a,E as s,a8 as h}from"./chunks/framework.BqC7ICod.js";const b=JSON.parse('{"title":"Demo","description":"Everything below runs in your browser. The controls are the options randName, randNickname, randWord and randSentence actually take, the code block under the…","frontmatter":{},"headers":[],"relativePath":"demo.md","filePath":"en/demo.md","lastUpdated":1788615057000}'),c={name:"demo.md"};function l(u,o,m,g,p,f){const t=r("Demo",!0);return d(),i("div",null,[o[0]||(o[0]=e("h1",{id:"demo",tabindex:"-1"},[a("Demo "),e("a",{class:"header-anchor",href:"#demo","aria-label":'Permalink to "Demo"'},"​")],-1)),o[1]||(o[1]=e("p",null,[a("Everything below runs in your browser. The controls are the options "),e("code",null,"randName"),a(", "),e("code",null,"randNickname"),a(", "),e("code",null,"randWord"),a(" and "),e("code",null,"randSentence"),a(" actually take, the code block under the output is the call your settings amount to, and what you see is drawn fresh every time you press Generate.")],-1)),s(t),o[2]||(o[2]=h('<h2 id="what-to-try" tabindex="-1">What to try <a class="header-anchor" href="#what-to-try" aria-label="Permalink to &quot;What to try&quot;">​</a></h2><ul><li>Set <code>language</code> to <code>en</code> and <code>realism</code> to <code>invented</code>. The names still read as English and stop being names anybody has — the generator builds them out of syllable templates instead of drawing from the pool.</li><li>Leave <code>language</code> on <code>all</code> and press Generate a few times. Nine scripts, and each name&#39;s length range is resolved for its own language rather than for the batch.</li><li>Pick <code>ru</code> and switch <code>gender</code>. Russian is the one language where the choice is visible from the outside: the patronymic and the surname both inflect.</li><li>On the nickname tab, set <code>theme</code> to <code>animal</code> and <code>wordSeparator</code> to <code>-</code>. The separator counts toward the length range, so a narrow range drops the modifier rather than truncating a word.</li><li>Set <code>maxLength</code> to <code>8</code> on an English nickname. The three-word shapes drop out rather than being truncated — length picks the shape, not the words.</li><li>Turn on <code>randSuffix</code>. The token is attached after the nickname is finished, which is why the length options never have to account for it.</li><li>On the words tab, pick a <code>theme</code> and press Generate. These are the pools a nickname is built from, handed over with nothing added — <code>randAnimal</code> and its twenty-four siblings are this call with the theme already chosen.</li><li>Switch the decorator to <code>randModifier</code> on the words tab. A modifier in front of a noun is most of what <code>randNickname</code> does, and the code block shows the two functions doing it in the open.</li><li>On the sentence tab, set <code>language</code> to <code>de</code> and then to <code>ru</code>, and turn on the details. Neither language offers an <code>object</code> or a <code>place</code>: both would put the noun in a case its own ending has to change for, so those shapes are not among the ones they declare.</li><li>Type two words into <code>include</code> — <code>brave lion</code> in English, <code>사자 조용히</code> in Korean. Both land in every sentence, and <code>brave</code> becomes a modifier or a predicate depending on what the rest of the shape has room for.</li><li>Set <code>shape</code> to <code>simple</code> and then to <code>complex</code>. The sentence gains a phrase rather than a longer word, which is the same thing <code>minLength</code> does one character at a time.</li></ul><h2 id="what-this-page-is-not" tabindex="-1">The scope of this page <a class="header-anchor" href="#what-this-page-is-not" aria-label="Permalink to &quot;The scope of this page {#what-this-page-is-not}&quot;">​</a></h2><p>This page is a demonstration rather than a generator to call from a browser at scale. The library itself has no network calls and no dependencies, so the same code runs on a server, in a build script or in a test fixture exactly as it runs here.</p><p>The output is also <strong>not seeded</strong>. There is no way to ask randino for the same batch twice; if you need reproducibility, keep the strings rather than the settings that produced them.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="./guide/getting-started">Getting started</a> — installing it, for whichever of the three packages you use.</li><li><a href="./name/rand-name"><code>randName</code></a>, <a href="./nickname/rand-nickname"><code>randNickname</code></a>, <a href="./word/rand-word"><code>randWord</code></a> and <a href="./sentence/rand-sentence"><code>randSentence</code></a> — every option in the panel above, written out.</li><li><a href="./guide/languages">Supported languages</a> — what each language can and cannot do.</li></ul>',7))])}const y=n(c,[["render",l]]);export{b as __pageData,y as default};
